        for (let j = 0; j < P.length; j += 2) { const x = dx + P[j], y = dy + P[j + 1], x2 = dx + P[(j + 2) % P.length], y2 = dy + P[(j + 3) % P.length]; j ? c.quadraticCurveTo(x, y, (x + x2) / 2, (y + y2) / 2) : c.moveTo((x + x2) / 2, (y + y2) / 2); }
        c.closePath(); c.fillStyle = rgba(b[0], b[1], b[2], 1); c.fill(); c.strokeStyle = rgba(b[0], b[1], b[2], 1); c.lineWidth = 4; c.stroke();
