    c.lineWidth = 1.6; c.strokeStyle = 'rgba(160,120,95,.8)'; for (const [rx, ry, cyy] of [[215, 400, 575], [190, 330, 600], [250, 470, 560]]) { c.beginPath(); c.ellipse(955, cyy, rx, ry, .03 * Math.sin(t), 0, TAU); c.stroke(); }
    c.strokeStyle = 'rgba(25,12,45,.5)'; c.lineWidth = 1.4; for (const [x, y, rx, ry, a0, a1] of [[930, 640, 300, 160, 3.4, 5.8], [900, 520, 160, 260, 4, 6.2]]) { c.beginPath(); c.ellipse(x, y, rx, ry, 0, a0, a1); c.stroke(); }
